import zipfile
import re
import xml.etree.ElementTree as ET

NS = {
    'm': 'http://schemas.openxmlformats.org/officeDocument/2006/main',
    'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
}

def col_to_idx(ref):
    m = re.match(r'([A-Z]+)(\d+)', ref)
    letters = m.group(1)
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - 64)
    return idx

with zipfile.ZipFile('budget.xlsx') as z:
    names = z.namelist()
    print('Archive entries:')
    for n in names:
        print(' ', n)

    shared = []
    if 'xl/sharedStrings.xml' in names:
        root = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in root.findall('m:si', NS):
            text = ''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/officeDocument/2006/main}t'))
            shared.append(text)

    wb_root = ET.fromstring(z.read('xl/workbook.xml'))
    sheets = wb_root.find('m:sheets', NS)
    sheet_list = []
    for s in sheets.findall('m:sheet', NS):
        sheet_list.append((s.get('name'), s.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')))

    rels_root = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    rel_map = {}
    for rel in rels_root.findall('{http://schemas.openxmlformats.org/package/2006/relationships}Relationship'):
        rel_map[rel.get('Id')] = rel.get('Target')

    for name, rid in sheet_list:
        target = rel_map[rid]
        if not target.startswith('xl/'):
            target = 'xl/' + target.lstrip('/')
        path = target
        print(f'\n=== Sheet: {name} (file: {path}) ===')
        sroot = ET.fromstring(z.read(path))
        for row in sroot.iter('{http://schemas.openxmlformats.org/officeDocument/2006/main}row'):
            for c in row.findall('m:c', NS):
                ref = c.get('r')
                t = c.get('t')
                v = c.find('m:v', NS)
                val = v.text if v is not None else None
                if t == 's' and val is not None:
                    val = shared[int(val)]
                print(f'{ref}: {val!r}')

import zipfile
import re
import xml.etree.ElementTree as ET

M = '{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'

with zipfile.ZipFile('budget.xlsx') as z:
    root = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))

cells = {}
for c in root.iter(M + 'c'):
    ref = c.get('r')
    t = c.get('t')
    v = c.find(M + 'v')
    isel = c.find(M + 'is')
    if t == 'inlineStr' and isel is not None:
        val = ''.join(x.text or '' for x in isel.iter(M + 't'))
    elif v is not None:
        val = float(v.text)
    else:
        val = None
    cells[ref] = val

def col(ref):
    return re.match(r'([A-Z]+)', ref).group(1)

def row(ref):
    return int(re.match(r'[A-Z]+(\d+)', ref).group(1))

# Expense line items: rows 11-22, values in column C, category in column A
cats = {}
for ref, val in cells.items():
    if col(ref) == 'C' and 11 <= row(ref) <= 22 and val is not None:
        cat_ref = 'A' + str(row(ref))
        cat = cells.get(cat_ref)
        cats.setdefault(cat, 0.0)
        cats[cat] += val
        print(f'{ref} ({cat}): {val:g}')

print('\nPer-category totals:')
total = 0.0
for cat, s in cats.items():
    print(f'  {cat}: {s:g}')
    total += s

print(f'\nTOTAL EXPENSES (sum of all categories): {total:g}')
print(f'File formula C23 = SUM(C11:C22): {cells.get("C23")!r}')
print(f'Total income B8 = SUM(B4:B7): {cells.get("B8")!r}')

